import os, socket
from pathlib import Path

states={'0A':'LISTEN'}
files=[('/proc/net/tcp','tcp4'),('/proc/net/tcp6','tcp6'),('/proc/net/udp','udp4'),('/proc/net/udp6','udp6')]

def decode_addr(hexaddr, proto):
    ip_hex, port_hex = hexaddr.split(':')
    port=int(port_hex,16)
    if proto.endswith('4'):
        raw=bytes.fromhex(ip_hex)
        ip=socket.inet_ntop(socket.AF_INET, raw[::-1])
    else:
        raw=bytes.fromhex(ip_hex)
        # /proc/net/tcp6 stores groups little-endian-ish; reverse each 4-byte word
        fixed=b''.join(raw[i:i+4][::-1] for i in range(0,16,4))
        ip=socket.inet_ntop(socket.AF_INET6, fixed)
    return ip,port

inode_to_proc={}
for pid in filter(str.isdigit, os.listdir('/proc')):
    fd_dir=f'/proc/{pid}/fd'
    try: fds=os.listdir(fd_dir)
    except Exception: continue
    for fd in fds:
        try: target=os.readlink(f'{fd_dir}/{fd}')
        except Exception: continue
        if target.startswith('socket:['):
            inode=target[8:-1]
            if inode not in inode_to_proc:
                try:
                    comm=Path(f'/proc/{pid}/comm').read_text().strip()
                except Exception: comm='?'
                try:
                    cmd=' '.join(Path(f'/proc/{pid}/cmdline').read_bytes().decode(errors='replace').split('\0')).strip()
                except Exception: cmd=''
                inode_to_proc[inode]=(pid,comm,cmd)

rows=[]
for path, proto in files:
    try: lines=Path(path).read_text().strip().splitlines()[1:]
    except Exception: continue
    for line in lines:
        parts=line.split()
        local=parts[1]; state=parts[3]; inode=parts[9]
        if proto.startswith('tcp') and state!='0A':
            continue
        # UDP has no LISTEN state; include bound sockets
        ip,port=decode_addr(local, proto)
        proc=inode_to_proc.get(inode, ('-','-',''))
        rows.append((port,proto,ip,proc[0],proc[1],proc[2]))

for port,proto,ip,pid,comm,cmd in sorted(rows):
    print(f'{proto:4} {ip}:{port:<5} pid={pid:<6} proc={comm:<16} cmd={cmd[:140]}')
